            out.append(("la rampe de la pile publiée de 259", [f"| ce bloc, pile publiée | **{_fr222(np_['de_centre_a_centre']['la_pente'])}** | **{_fr222(np_['a_la_couture']['la_pente'])}** |"], s259.name))
